<?php declare(strict_types=1); $e=static fn(mixed $v): string => htmlspecialchars((string)$v, ENT_QUOTES, "UTF-8"); ?><style>.cr-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.cr-stat{padding:22px;border-radius:14px}.cr-stat .n{font-size:30px;font-weight:700}.cr-muted{color:#667085}.cr-actions{display:flex;gap:8px;flex-wrap:wrap}.cr-badge{display:inline-block;padding:5px 9px;border-radius:999px;font-size:12px;background:#eef2f6}@media(max-width:900px){.cr-grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr!important}}</style><div class="page-header"><div><h1><?= $e($record['request_no'] ?? 'Rental Request') ?></h1><p><?= $e($record['customer_name'] ?? '') ?> · <?= $e($record['customer_phone'] ?? '') ?></p></div><div class="page-actions"><a class="btn btn-secondary" href="<?= config('app.base_path') ?>/commercial-rentals/requests">Back</a><a class="btn btn-primary" href="<?= config('app.base_path') ?>/commercial-rentals/requests/<?= (int)$record['id'] ?>/edit">Edit</a></div></div><div class="card"><h2>Workflow Status</h2><form method="POST" action="<?= config('app.base_path') ?>/commercial-rentals/requests/<?= (int)$record['id'] ?>/status" class="cr-actions"><select name="status"><?php foreach(['REQUESTED','CONTACTING','QUOTED','CONFIRMED','IN_PROGRESS','COMPLETED','CANCELLED','REJECTED'] as $s): ?><option value="<?= $s ?>" <?= ($record['status']??'')===$s?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select><button class="btn btn-primary">Update Status</button></form></div><div class="card"><table class="table"><tbody><?php foreach(['customer_name'=>'Customer','customer_phone'=>'Phone','purpose'=>'Purpose','pickup_address'=>'Pickup / Work Location','pickup_lat'=>'Pickup Latitude','pickup_lng'=>'Pickup Longitude','destination_address'=>'Destination','start_at'=>'Start','end_at'=>'End','duration_text'=>'Duration','operator_required'=>'Operator Required','provider_name'=>'Provider','vehicle_name'=>'Vehicle / Equipment','status'=>'Status','quoted_amount'=>'Quoted Amount','final_amount'=>'Final Amount','customer_notes'=>'Customer Notes','admin_notes'=>'Admin Notes','created_at'=>'Created At','updated_at'=>'Updated At'] as $key=>$label): ?><tr><th><?= $e($label) ?></th><td><?= $e($record[$key] ?? '—') ?></td></tr><?php endforeach; ?></tbody></table></div>
